import{_ as t,o as d,c as o,a4 as a}from"./chunks/framework.DpieW3qv.js";const u=JSON.parse('{"title":"Command Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/commands.md","filePath":"reference/commands.md","lastUpdated":null}'),s={name:"reference/commands.md"};function r(c,e,i,l,n,h){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="command-reference" tabindex="-1">Command Reference <a class="header-anchor" href="#command-reference" aria-label="Permalink to &quot;Command Reference&quot;">​</a></h1><p>Quick reference for all Makefile commands. For full syntax, flags, and example output, use the per-command pages under <a href="/ocapi-docs.github.io/cli/">Commands</a>.</p><h2 id="command-summary" tabindex="-1">Command summary <a class="header-anchor" href="#command-summary" aria-label="Permalink to &quot;Command summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Command</th><th>What it does</th><th>Typical output</th></tr></thead><tbody><tr><td>Setup</td><td><code>make setup</code></td><td>Configure brand, data source, OCAPI</td><td>Wizard; writes <code>dev-env/.ocapi-config.json</code></td></tr><tr><td>Setup</td><td><code>make health</code></td><td>Test SFCC connection</td><td><code>✔ OCAPI ready (NNNms)</code> or missing-env errors</td></tr><tr><td>1</td><td><code>make pull</code></td><td>Git sync + fetch + auto-build, then open status hub</td><td>Progress spinners; auto-builds only missing dates; opens status</td></tr><tr><td>2</td><td><code>make preview</code></td><td>Build if stale (diff + approval) + compose + preview file browser</td><td>Shows changes for approval if data changed; file browser for preview/ folder</td></tr><tr><td>3</td><td><code>make push</code></td><td>Validate + sync to SFCC + auto-email + replicate steps</td><td><code>✔ Synced …</code> + email + replication steps + staging URL</td></tr><tr><td>4</td><td><code>make commit</code></td><td>Save to Git (refresh dir only)</td><td><code>✔ Committed: brand date done</code></td></tr><tr><td>Status</td><td><code>make status</code></td><td>Interactive hub — pick refresh → pick action → run → back to board</td><td>Summary + picker (TTY) or full table</td></tr><tr><td>Also</td><td><code>make build</code></td><td>Build only (preview without zone picker)</td><td><code>✔ N files generated</code> or approval prompt</td></tr><tr><td>Also</td><td><code>make browse</code></td><td>Browse data files (assets, refresh.json, payload)</td><td>Tree view + file picker</td></tr><tr><td>Also</td><td><code>make replicate</code></td><td>Print replication steps (STG → POD)</td><td>Plain-text steps + staging URL</td></tr><tr><td>Also</td><td><code>make email</code></td><td>Generate changeout email (also runs automatically after <code>make push</code>)</td><td>Email body</td></tr><tr><td>Also</td><td><code>make excel</code></td><td>Parse Excel into refresh data (no build)</td><td>Writes <code>refresh.json</code> per date</td></tr><tr><td>Dev</td><td><code>make delete DATE=</code></td><td>Remove refresh from SFCC + local</td><td><code>✔ SFCC deleted</code> / <code>✔ Deleted local</code></td></tr><tr><td>Dev</td><td><code>make upload</code></td><td>Partial asset sync (push HTML changes only)</td><td>Sync summary</td></tr><tr><td>Dev</td><td><code>make registry</code></td><td>Show live asset registry</td><td>Zone list + item counts</td></tr><tr><td>Dev</td><td><code>make registry ARGS=&quot;--ipids&quot;</code></td><td>List all IPIDs in the registry</td><td>Asset type, zone, order, IPID</td></tr><tr><td>Dev</td><td><code>make test</code></td><td>Run all tests (Vitest)</td><td><code>Tests N passed</code></td></tr><tr><td>Dev</td><td><code>make test-watch</code></td><td>Run tests in watch mode</td><td>Re-runs on file change</td></tr><tr><td>Dev</td><td><code>make test-coverage</code></td><td>Run tests with coverage report (threshold: 64% statements)</td><td>Coverage summary + lcov</td></tr><tr><td>Dev</td><td><code>make test-brands</code></td><td>E2E test both brands (clean dev-env → excel → build → preview)</td><td>Per-brand output</td></tr><tr><td>Dev</td><td><code>make fresh-install</code></td><td>Full reset: remove dev-env + node_modules, npm ci, then make test-brands</td><td>Reinstall + E2E</td></tr><tr><td>Dev</td><td><code>make convert-excel INPUT=</code> [OUTPUT=]</td><td>Raw Excel → CONVERTED format (INPUT required)</td><td>Writes converted file</td></tr><tr><td>Dev</td><td><code>make check</code></td><td>Lint + tests + audit (CI gate)</td><td>Lint + test + audit output</td></tr><tr><td>Dev</td><td><code>make clean</code></td><td>Remove rendered previews</td><td><code>✔ Cleaned</code></td></tr><tr><td>Dev</td><td><code>make docs</code></td><td>Generate API docs + start VitePress dev server</td><td>VitePress URL</td></tr><tr><td>Dev</td><td><code>make docs-gen</code></td><td>Regenerate API and template reference docs</td><td>Writes to <code>docs/reference/</code></td></tr><tr><td>Dev</td><td><code>make docs-build</code></td><td>Generate docs + build VitePress for production</td><td>Static site in <code>docs/.vitepress/dist</code></td></tr><tr><td>Dev</td><td><code>make docs-deploy</code></td><td>Build + deploy docs to GitHub Pages</td><td>Published URL</td></tr><tr><td>Dev</td><td><code>make lint-docs</code></td><td>Lint action types in doc files</td><td>Pass/fail</td></tr><tr><td>Dev</td><td><code>make reports [OP=dates]</code></td><td>Report: dates, stats, status, pending, history</td><td>See <a href="/ocapi-docs.github.io/cli/reports.html">reports</a></td></tr><tr><td>Dev</td><td><code>make validate [DATE=]</code></td><td>Data quality check only (no build/push)</td><td>See <a href="/ocapi-docs.github.io/cli/validate.html">validate</a></td></tr><tr><td>CI</td><td><code>make test-sync DATE=</code></td><td>Push to OCAPI with <code>--yes --force</code> (CI / non-interactive)</td><td>Sync output</td></tr><tr><td>CI</td><td><code>make build-all [FORCE=1]</code></td><td>Build <strong>every</strong> date for current brand</td><td>Per-date build output</td></tr><tr><td>CI</td><td><code>make push-all [YES=1] [FORCE=1]</code></td><td>Sync <strong>every</strong> date to SFCC (run after build-all)</td><td>Per-date sync output</td></tr><tr><td>Diag</td><td><code>make config</code></td><td>Print current configuration (no secrets; env var presence only)</td><td>Config summary</td></tr><tr><td>Diag</td><td><code>make doctor</code></td><td>Validate setup, config, brand, source, refresh dirs, OCAPI env</td><td>Pass/fail checklist</td></tr></tbody></table><p><strong>Test commands:</strong> Run <code>make test</code> for the full suite. Use <code>make test-watch</code> for watch mode, <code>make test-coverage</code> for coverage, and <code>make test-brands</code> for E2E both brands. Use <code>make fresh-install</code> for a full reset (deps + dev-env) then E2E. To run a subset by path: <code>npx vitest run tests/domain</code> or <code>npx vitest run tests/cli</code>.</p><p><strong>Approval guards:</strong> When data has already been built or synced and you run <code>make build</code> or <code>make push</code> again, the tool shows what changed (copy, destinations, items added/removed) and asks for approval instead of blocking. Use <code>FORCE=1</code> to skip the prompt (e.g., in CI). Use <code>YES=1</code> to auto-approve.</p><p><strong>build-all / push-all:</strong> For CI or batch runs. Run <code>make pull</code> first; then <code>make build-all</code> builds all dates; then <code>make push-all</code> syncs all of them to SFCC. Use <code>YES=1</code> to skip confirmation prompts. Use <code>FAIL_FAST=1</code> to stop on first failure (default: continue on error).</p><p><strong>Automation:</strong> For scripts and CI, use <code>DATE=</code>, <code>REFRESH=</code>, <code>YES=1</code>, <code>FORCE=1</code> as needed. Use <code>VERBOSE=1</code> for run IDs on log lines. Use <code>FAIL_FAST=1</code> for fail-fast batch runs, and <code>ARGS=&quot;...&quot;</code> to pass extra CLI flags.</p><h2 id="make-variables-→-cli-flags" tabindex="-1">Make variables → CLI flags <a class="header-anchor" href="#make-variables-→-cli-flags" aria-label="Permalink to &quot;Make variables → CLI flags&quot;">​</a></h2><p>The Makefile is the source of truth. All commands are invoked via <code>make &lt;target&gt;</code>; the CLI receives variables as flags.</p><table tabindex="0"><thead><tr><th>Make variable</th><th>CLI flag / behaviour</th><th>Example</th></tr></thead><tbody><tr><td><code>BRAND</code></td><td>First positional arg after command</td><td><code>make build</code> → <code>node … refresh loft</code></td></tr><tr><td><code>DATE</code></td><td><code>--date=YYYY-MM-DD</code></td><td><code>make build DATE=2026-02-14</code></td></tr><tr><td><code>REFRESH</code></td><td><code>--refresh=r1</code></td><td><code>make push REFRESH=r2</code></td></tr><tr><td><code>FORCE=1</code></td><td><code>--force</code></td><td><code>make build FORCE=1</code></td></tr><tr><td><code>YES=1</code></td><td><code>--yes</code> (skip confirmation/approval prompts)</td><td><code>make push-all YES=1</code></td></tr><tr><td><code>ALL=1</code></td><td><code>build</code>/<code>push</code>: <code>--all-refreshes</code> (all refreshes in a date); <code>status</code>: <code>--show-all</code> (full history)</td><td><code>make status ALL=1</code></td></tr><tr><td><code>FAIL_FAST=1</code></td><td>Stop <code>build-all</code>/<code>push-all</code> on first failure (default: continue)</td><td><code>make build-all FAIL_FAST=1</code></td></tr><tr><td><code>ARGS=&quot;...&quot;</code></td><td>Pass extra CLI flags (appended after mapped vars)</td><td><code>make push ARGS=&quot;--yes --force&quot;</code></td></tr><tr><td><code>SKIP_FETCH=1</code></td><td><code>--skip-fetch</code></td><td><code>make pull SKIP_FETCH=1</code></td></tr><tr><td><code>CONVERT=1</code></td><td><code>--convert</code></td><td><code>make pull CONVERT=1</code></td></tr><tr><td><code>PULL=1</code></td><td>status: <code>--pull</code> (bypass throttles)</td><td><code>make status PULL=1</code></td></tr><tr><td><code>STATUS_REFRESH_INDEX</code></td><td>status (non-TTY): 0-based index of refresh row to act on</td><td><code>STATUS_REFRESH_INDEX=2 make status</code></td></tr><tr><td><code>STATUS_ACTION_INDEX</code></td><td>status (non-TTY): 0-based index of action (0=Browse, 1=Push, 2=Commit, 3=Rebuild force, 4=Email, 5=View data quality, 6=Pull)</td><td><code>STATUS_ACTION_INDEX=1 make status</code></td></tr><tr><td><code>VERBOSE=1</code></td><td><code>--verbose</code></td><td><code>make push VERBOSE=1</code></td></tr><tr><td><code>COPY=1</code></td><td><code>--copy</code></td><td><code>make email COPY=1</code></td></tr><tr><td><code>OP</code></td><td>reports operation (dates, stats, status, pending, history)</td><td><code>make reports OP=stats</code> (default: dates)</td></tr></tbody></table><p><strong>Source &amp; OCAPI:</strong> Use <code>make setup</code> to switch data source (local/Smartsheet) and enable/disable SFCC sync. The setup wizard handles brand, source, and OCAPI configuration.</p><h2 id="commit" tabindex="-1">commit <a class="header-anchor" href="#commit" aria-label="Permalink to &quot;commit {#commit}&quot;">​</a></h2><p>Save the selected refresh to Git. The commit message is generated from brand, date, and refresh; Git is invoked via an argument list (no shell), so paths and messages are safe from injection. Use after <code>make push</code> and replication.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="browse" tabindex="-1">browse <a class="header-anchor" href="#browse" aria-label="Permalink to &quot;browse {#browse}&quot;">​</a></h2><p>Interactive file picker for data files in the active refresh (assets/*.json, refresh.json, ocapi-payload.json). Use arrow keys to browse, Enter to select (prints path), q to exit. The <a href="/ocapi-docs.github.io/cli/status.html">status</a> hub also offers a &quot;Browse files&quot; action (data + templates + rendered in one picker).</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> browse</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> browse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DATE=2026-02-14</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="select" tabindex="-1">select (use status) <a class="header-anchor" href="#select" aria-label="Permalink to &quot;select (use status) {#select}&quot;">​</a></h2><p>There is no <code>make select</code> target. Use <strong><code>make status</code></strong> to open the interactive hub and pick a refresh: <code>make status</code>, <code>make status DATE=2026-02-14</code>, or <code>make status DATE=2026-02-14/r2</code> to pre-select a refresh. For scripted selection, use <code>sfcc select loft DATE=2026-02-14</code> (or <code>ann</code>). See <a href="/ocapi-docs.github.io/cli/status.html">status</a>.</p><h2 id="per-command-pages" tabindex="-1">Per-command pages <a class="header-anchor" href="#per-command-pages" aria-label="Permalink to &quot;Per-command pages&quot;">​</a></h2><ul><li><strong>Producer:</strong> <a href="/ocapi-docs.github.io/cli/status.html">status</a> · <a href="/ocapi-docs.github.io/cli/pull.html">pull</a> · <a href="/ocapi-docs.github.io/cli/preview.html">preview</a> · <a href="/ocapi-docs.github.io/cli/push.html">push</a> · <a href="/ocapi-docs.github.io/cli/build.html">build</a> · <a href="/ocapi-docs.github.io/cli/replicate.html">replicate</a> · <a href="/ocapi-docs.github.io/cli/email.html">email</a> — commit, browse, select: see <a href="#commit">above</a></li><li><strong>Dev &amp; Ops:</strong> <a href="/ocapi-docs.github.io/cli/setup.html">setup</a> · <a href="/ocapi-docs.github.io/cli/upload.html">upload</a> · <a href="/ocapi-docs.github.io/cli/delete.html">delete</a> · <a href="/ocapi-docs.github.io/cli/registry.html">registry</a> · <a href="/ocapi-docs.github.io/cli/health.html">health</a> · <a href="/ocapi-docs.github.io/cli/excel.html">excel</a> · <a href="/ocapi-docs.github.io/cli/reports.html">reports</a> · <a href="/ocapi-docs.github.io/cli/validate.html">validate</a></li></ul><p>For full workflow and example output, see <a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer Workflow</a>. For a walkthrough of blocking errors and approval steps, see <a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer Workflow</a>.</p>`,23)])])}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
